#include <iostream>
#include <vector>
int maximum(const std::vector<int>& v){ int best=v.at(0); for(std::size_t i=1;i<v.size();++i) if(v[i]>best) best=v[i]; return best; }
int main(){ std::cout<<maximum({4,9,2,7})<<'\n'; }

#include <cassert>
#include <vector>
int sum(const std::vector<int>& v){ int total=0; for(std::size_t i=0;i<v.size();++i){ total+=v[i]; /* invariant: total equals sum of v[0..i] */ } return total; }
int main(){ assert(sum({})==0); assert(sum({1,2,3})==6); }
